// SmartHelmet/Software/src/components/SurveillanceTunnelMap.jsx

import { useMemo } from 'react';
import { TUNNEL_GRAPH, THRESHOLDS } from '../utils/constants';
import { runDijkstra } from '../services/api';
import '../styles/SurveillanceTunnelMap.css';

/* ═══════════════════════════════════════════════════════
   LAYOUT CONSTANTS — Handcrafted for surveillance aesthetic
   ViewBox: 0 0 860 460
   ═══════════════════════════════════════════════════════ */

const VB_W = 860;
const VB_H = 460;

/** Node positions optimised for wide-format surveillance display */
const NODES = {
  'Entrance':       { x: 85,  y: 258 },
  'Main Junction':  { x: 265, y: 242 },
  'West Junction':  { x: 415, y: 128 },
  'East Junction':  { x: 570, y: 332 },
  'Zone A':         { x: 285, y: 60  },
  'Zone B':         { x: 510, y: 202 },
  'Zone C':         { x: 730, y: 132 },
};

/** Edges with curvature (perpendicular offset fraction) */
const EDGES = [
  { from: 'Entrance',      to: 'Main Junction',  curve: 0.04  },
  { from: 'Main Junction', to: 'West Junction',   curve: 0.08  },
  { from: 'Main Junction', to: 'East Junction',   curve: -0.05 },
  { from: 'West Junction', to: 'Zone A',          curve: -0.12 },
  { from: 'West Junction', to: 'Zone B',          curve: 0.06  },
  { from: 'East Junction', to: 'Zone B',          curve: 0.09  },
  { from: 'East Junction', to: 'Zone C',          curve: -0.07 },
];

/** Decorative branch lines for organic mine-tunnel feel */
const BRANCHES = [
  // Off Entrance → Main tunnel
  { x1: 135, y1: 253, x2: 118, y2: 218 }, { x1: 135, y1: 253, x2: 120, y2: 290 },
  { x1: 185, y1: 249, x2: 198, y2: 214 }, { x1: 185, y1: 249, x2: 172, y2: 288 },
  { x1: 225, y1: 246, x2: 235, y2: 278 },
  // Off Main Junction area
  { x1: 265, y1: 242, x2: 245, y2: 274 }, { x1: 265, y1: 242, x2: 280, y2: 278 },
  // Off Main → West tunnel
  { x1: 320, y1: 200, x2: 305, y2: 168 }, { x1: 365, y1: 168, x2: 350, y2: 140 },
  { x1: 385, y1: 152, x2: 400, y2: 118 },
  // Off Main → East tunnel
  { x1: 355, y1: 268, x2: 342, y2: 300 }, { x1: 425, y1: 290, x2: 440, y2: 322 },
  { x1: 498, y1: 312, x2: 512, y2: 348 }, { x1: 530, y1: 324, x2: 542, y2: 360 },
  // Near Zone A
  { x1: 285, y1: 60, x2: 258, y2: 38 }, { x1: 285, y1: 60, x2: 312, y2: 36 },
  { x1: 335, y1: 92, x2: 358, y2: 62 },
  // Near Zone B
  { x1: 510, y1: 202, x2: 540, y2: 175 }, { x1: 510, y1: 202, x2: 535, y2: 228 },
  // Off East → Zone B
  { x1: 545, y1: 272, x2: 562, y2: 248 },
  // Off East → Zone C
  { x1: 635, y1: 258, x2: 655, y2: 228 }, { x1: 678, y1: 205, x2: 698, y2: 178 },
  // Near Zone C
  { x1: 730, y1: 132, x2: 760, y2: 108 }, { x1: 730, y1: 132, x2: 758, y2: 160 },
  { x1: 730, y1: 132, x2: 765, y2: 130 },
  // Near East Junction
  { x1: 570, y1: 332, x2: 552, y2: 366 }, { x1: 570, y1: 332, x2: 598, y2: 358 },
  // Near Entrance
  { x1: 85, y1: 258, x2: 58, y2: 232 }, { x1: 85, y1: 258, x2: 55, y2: 278 },
  { x1: 85, y1: 258, x2: 50, y2: 256 },
];

/** Zone letter overlays — large background labels */
const ZONE_LETTERS = [
  { letter: 'A', x: 210, y: 98,  color: 'rgba(0, 200, 255, 0.08)', size: 48 },
  { letter: 'B', x: 485, y: 248, color: 'rgba(0, 200, 255, 0.08)', size: 48 },
  { letter: 'C', x: 745, y: 178, color: 'rgba(0, 200, 255, 0.08)', size: 48 },
];

/* ═══════════════════════════════════════════════════════
   HELPERS
   ═══════════════════════════════════════════════════════ */

/** Quadratic Bézier path between two nodes with curvature offset */
function curvedPath(n1, n2, curvature = 0) {
  const mx = (n1.x + n2.x) / 2;
  const my = (n1.y + n2.y) / 2;
  const dx = n2.x - n1.x;
  const dy = n2.y - n1.y;
  const cx = mx - dy * curvature;
  const cy = my + dx * curvature;
  return `M${n1.x},${n1.y} Q${cx},${cy} ${n2.x},${n2.y}`;
}

/** Derive hazard label from sensor reading */
function getHazardLabel(reading) {
  if (!reading) return 'HAZARD ZONE';
  if (reading.gas_level >= THRESHOLDS.gas_level.warning) return 'GAS HAZARD';
  if (reading.temperature >= THRESHOLDS.temperature.warning) return 'HEAT HAZARD';
  if (reading.force >= THRESHOLDS.force.warning) return 'IMPACT ALERT';
  const hr = reading.heart_rate;
  if (hr > 0 && (hr <= THRESHOLDS.heart_rate.warningLow || hr >= THRESHOLDS.heart_rate.warningHigh))
    return 'VITAL ALERT';
  return 'HAZARD ZONE';
}

/* ═══════════════════════════════════════════════════════
   COMPONENT
   ═══════════════════════════════════════════════════════ */

export default function SurveillanceTunnelMap({ worker, reading, zone, status }) {
  const isDanger  = status === 'warning' || status === 'emergency';
  const isEmergency = status === 'emergency';
  const workerPos = zone && NODES[zone] ? NODES[zone] : null;
  const rssi      = reading?.rssi ?? null;
  const workerLabel = worker?.name || worker?.worker_id || 'Worker';
  const statusLabel = isEmergency ? 'EMERGENCY' : isDanger ? 'WARNING' : 'ALL CLEAR';

  /* ── Rescue route (Dijkstra) — only computed during danger ── */
  const rescueRoute = useMemo(() => {
    if (!isDanger || !zone || zone === 'Entrance') return [];
    return runDijkstra(TUNNEL_GRAPH, 'Entrance', zone);
  }, [isDanger, zone]);

  /* ── Build set of edges on the rescue path for fast lookup ── */
  const rescueEdgeSet = useMemo(() => {
    const set = new Set();
    for (let i = 0; i < rescueRoute.length - 1; i++) {
      set.add([rescueRoute[i], rescueRoute[i + 1]].sort().join('|'));
    }
    return set;
  }, [rescueRoute]);

  /* ── Pre-compute all edge path strings ── */
  const edgePaths = useMemo(
    () =>
      EDGES.map((e) => ({
        ...e,
        d: curvedPath(NODES[e.from], NODES[e.to], e.curve),
        key: [e.from, e.to].sort().join('|'),
      })),
    []
  );

  /* ── Hazard visuals ── */
  const hazardLabel   = isDanger ? getHazardLabel(reading) : '';
  const hazardColor   = isEmergency ? '#ef4444' : '#f97316';
  const hazardRadius  = isEmergency ? 62 : 52;

  return (
    <div className="surveillance-map-card">
      {/* ── Header ────────────────────────────────── */}
      <div className="surveillance-map-header">
        <div className="stm-header-left">
          <span className="surveillance-map-title">Tunnel Surveillance Map</span>
          <span className="surveillance-map-subtitle">Live position and rescue route guidance</span>
        </div>
        <span className={`stm-status-badge ${status || 'normal'}`}>
          <span className={`stm-status-dot ${status || 'normal'}`} />
          {statusLabel}
        </span>
      </div>

      {/* ── SVG Canvas ────────────────────────────── */}
      <div className="surveillance-map-canvas">
        {/* Awaiting location overlay */}
        {!workerPos && (
          <div className="stm-awaiting-overlay">
            <div className="stm-awaiting-icon">📡</div>
            <div className="stm-awaiting-text">Awaiting location data</div>
          </div>
        )}

        <svg viewBox={`0 0 ${VB_W} ${VB_H}`} preserveAspectRatio="xMidYMid meet">
          {/* ── Defs: patterns, filters ──────────── */}
          <defs>
            {/* Blueprint grid */}
            <pattern id="stm-grid" width="28" height="28" patternUnits="userSpaceOnUse">
              <path d="M 28 0 L 0 0 0 28" fill="none" stroke="rgba(0,180,255,0.035)" strokeWidth="0.5" />
            </pattern>

            {/* Tunnel glow */}
            <filter id="stm-tun-glow" x="-15%" y="-15%" width="130%" height="130%">
              <feGaussianBlur in="SourceGraphic" stdDeviation="2.5" result="b" />
              <feMerge><feMergeNode in="b" /><feMergeNode in="SourceGraphic" /></feMerge>
            </filter>

            {/* Rescue path glow */}
            <filter id="stm-rescue-glow" x="-20%" y="-20%" width="140%" height="140%">
              <feGaussianBlur in="SourceGraphic" stdDeviation="4" result="b" />
              <feMerge><feMergeNode in="b" /><feMergeNode in="SourceGraphic" /></feMerge>
            </filter>

            {/* Worker marker glow */}
            <filter id="stm-worker-glow" x="-60%" y="-60%" width="220%" height="220%">
              <feGaussianBlur in="SourceGraphic" stdDeviation="5" result="b" />
              <feMerge><feMergeNode in="b" /><feMergeNode in="SourceGraphic" /></feMerge>
            </filter>

            {/* Hazard glow */}
            <filter id="stm-hazard-glow" x="-20%" y="-20%" width="140%" height="140%">
              <feGaussianBlur in="SourceGraphic" stdDeviation="3" result="b" />
              <feMerge><feMergeNode in="b" /><feMergeNode in="SourceGraphic" /></feMerge>
            </filter>

            {/* Node inner gradient */}
            <radialGradient id="stm-node-fill">
              <stop offset="0%" stopColor="rgba(0,212,255,0.15)" />
              <stop offset="100%" stopColor="rgba(6,11,40,0.8)" />
            </radialGradient>
          </defs>

          {/* ── Layer 0: Grid background ──────────── */}
          <rect width={VB_W} height={VB_H} fill="url(#stm-grid)" />

          {/* ── Layer 1: Zone letter watermarks ───── */}
          {ZONE_LETTERS.map((z) => (
            <text
              key={z.letter}
              x={z.x}
              y={z.y}
              fill={z.color}
              fontSize={z.size}
              fontWeight="800"
              fontFamily="'Plus Jakarta Sans', sans-serif"
              textAnchor="middle"
              dominantBaseline="central"
              style={{ pointerEvents: 'none', userSelect: 'none' }}
            >
              {z.letter}
            </text>
          ))}

          {/* ── Layer 2: Decorative branch tunnels ── */}
          <g opacity={0.28}>
            {BRANCHES.map((b, i) => (
              <line
                key={`br-${i}`}
                x1={b.x1} y1={b.y1} x2={b.x2} y2={b.y2}
                stroke="rgba(0,160,220,0.45)"
                strokeWidth={1.8}
                strokeLinecap="round"
              />
            ))}
          </g>

          {/* ── Layer 3: Main tunnel network ──────── */}
          <g filter="url(#stm-tun-glow)">
            {edgePaths.map((e) => (
              <path
                key={e.key}
                d={e.d}
                fill="none"
                stroke="rgba(0,180,255,0.45)"
                strokeWidth={4}
                strokeLinecap="round"
              />
            ))}
          </g>
          {/* Brighter core line on top */}
          {edgePaths.map((e) => (
            <path
              key={`${e.key}-core`}
              d={e.d}
              fill="none"
              stroke="rgba(0,210,255,0.2)"
              strokeWidth={1.5}
              strokeLinecap="round"
            />
          ))}

          {/* ── Layer 4: Rescue path (ONLY during danger) ── */}
          {isDanger && rescueRoute.length > 1 && (
            <g filter="url(#stm-rescue-glow)" className="stm-rescue-path-anim">
              {edgePaths
                .filter((e) => rescueEdgeSet.has(e.key))
                .map((e) => (
                  <g key={`rescue-${e.key}`}>
                    {/* Outer glow stroke */}
                    <path
                      d={e.d}
                      fill="none"
                      stroke={isEmergency ? 'rgba(34,197,94,0.55)' : 'rgba(34,197,94,0.38)'}
                      strokeWidth={isEmergency ? 12 : 9}
                      strokeLinecap="round"
                    />
                    {/* Main rescue line */}
                    <path
                      d={e.d}
                      fill="none"
                      stroke="#22c55e"
                      strokeWidth={isEmergency ? 5 : 3.5}
                      strokeLinecap="round"
                    />
                    {/* Animated dash overlay */}
                    <path
                      className="stm-rescue-dash-anim"
                      d={e.d}
                      fill="none"
                      stroke="rgba(255,255,255,0.3)"
                      strokeWidth={1.5}
                      strokeLinecap="round"
                      strokeDasharray="8 16"
                    />
                  </g>
                ))}
            </g>
          )}

          {/* ── Layer 5: Hazard zone (ONLY during danger) ── */}
          {isDanger && workerPos && (
            <g
              filter="url(#stm-hazard-glow)"
              className={isEmergency ? 'stm-hazard-region-emergency' : 'stm-hazard-region-warning'}
            >
              {/* Hazard area fill */}
              <circle
                cx={workerPos.x}
                cy={workerPos.y}
                r={hazardRadius}
                fill={isEmergency ? 'rgba(239,68,68,0.06)' : 'rgba(249,115,22,0.04)'}
                stroke={isEmergency ? 'rgba(239,68,68,0.45)' : 'rgba(249,115,22,0.35)'}
                strokeWidth={1.5}
                strokeDasharray="8 5"
              />
              {/* Warning triangle icon — positioned above hazard zone */}
              <g transform={`translate(${workerPos.x}, ${workerPos.y - hazardRadius - 18})`}>
                <path
                  d="M0,-10 L9,6 L-9,6 Z"
                  fill="none"
                  stroke={hazardColor}
                  strokeWidth={1.5}
                  strokeLinejoin="round"
                />
                <line x1={0} y1={-5} x2={0} y2={1} stroke={hazardColor} strokeWidth={1.8} strokeLinecap="round" />
                <circle cx={0} cy={3.5} r={1} fill={hazardColor} />
              </g>
              {/* Hazard label */}
              <text
                x={workerPos.x}
                y={workerPos.y - hazardRadius - 32}
                textAnchor="middle"
                fill={hazardColor}
                fontSize={9}
                fontWeight="700"
                fontFamily="'Plus Jakarta Sans', sans-serif"
                letterSpacing="0.08em"
              >
                {hazardLabel}
              </text>
            </g>
          )}

          {/* ── Layer 6: Junction / zone nodes ────── */}
          {Object.entries(NODES).map(([name, pos]) => {
            const isActive = name === zone;
            if (isActive) return null; // Worker marker drawn separately
            const isJunction = name.includes('Junction');
            const r = isJunction ? 6 : 5;
            return (
              <g key={name}>
                <circle
                  cx={pos.x} cy={pos.y} r={r}
                  fill="url(#stm-node-fill)"
                  stroke="rgba(0,200,255,0.35)"
                  strokeWidth={1.2}
                />
                {/* Centre dot */}
                <circle cx={pos.x} cy={pos.y} r={1.8} fill="rgba(0,212,255,0.5)" />
                {/* Label */}
                {name !== 'Entrance' && (
                  <text
                    x={pos.x}
                    y={pos.y + (name.startsWith('Zone') ? 20 : 22)}
                    textAnchor="middle"
                    fill="rgba(160,174,192,0.55)"
                    fontSize={8}
                    fontWeight="600"
                    fontFamily="'Plus Jakarta Sans', sans-serif"
                  >
                    {name}
                  </text>
                )}
              </g>
            );
          })}

          {/* ── Layer 7: Entrance marker ──────────── */}
          <g>
            {/* Arch icon */}
            <g transform={`translate(${NODES.Entrance.x - 32}, ${NODES.Entrance.y})`}>
              <rect x={-9} y={-4} width={18} height={13} rx={1}
                fill="none" stroke="rgba(0,212,255,0.4)" strokeWidth={1.2} />
              <path d="M-6,-4 L-6,-11 A6,8 0 0,1 6,-11 L6,-4"
                fill="none" stroke="rgba(0,212,255,0.4)" strokeWidth={1.2} />
            </g>
            {/* ENTRANCE label */}
            <text
              x={NODES.Entrance.x - 32}
              y={NODES.Entrance.y + 22}
              textAnchor="middle"
              fill="rgba(0,212,255,0.5)"
              fontSize={8}
              fontWeight="700"
              fontFamily="'Plus Jakarta Sans', sans-serif"
              letterSpacing="0.08em"
            >
              ENTRANCE
            </text>
          </g>

          {/* ── Layer 8: Worker marker ────────────── */}
          {workerPos && (
            <g transform={`translate(${workerPos.x}, ${workerPos.y})`}>
              <g className="stm-worker-pulse-group" style={{ transformOrigin: '0px 0px' }}>
                {/* Outer glow ring */}
                <circle r={22} fill="none" stroke="rgba(0,212,255,0.15)" strokeWidth={1}
                  filter="url(#stm-worker-glow)" />
                {/* Middle ring */}
                <circle r={16} fill="rgba(0,212,255,0.06)" stroke="rgba(0,212,255,0.3)" strokeWidth={1.5} />
                {/* Inner solid */}
                <circle r={10} fill="rgba(0,212,255,0.12)" stroke="#00d4ff" strokeWidth={1.5} />

                {/* Person icon */}
                <circle cy={-4.5} r={2.8} fill="#00d4ff" />
                <rect x={-2.8} y={-1} width={5.6} height={5.5} rx={1.4} fill="#00d4ff" />
                <rect x={-2.5} y={5} width={2} height={4} rx={0.8} fill="#00d4ff" />
                <rect x={0.5} y={5} width={2} height={4} rx={0.8} fill="#00d4ff" />
              </g>

              {/* Worker name badge */}
              <rect
                x={-24} y={28} width={48} height={16} rx={6}
                fill="rgba(0,212,255,0.12)"
                stroke="rgba(0,212,255,0.2)"
                strokeWidth={0.7}
              />
              <text
                x={0} y={39}
                textAnchor="middle"
                fill="#00d4ff"
                fontSize={8}
                fontWeight="700"
                fontFamily="'JetBrains Mono', 'Fira Code', monospace"
              >
                {workerLabel}
              </text>
            </g>
          )}

          {/* ── Layer 9: North indicator ──────────── */}
          <g transform="translate(36, 36)">
            <circle r={15} fill="none" stroke="rgba(0,212,255,0.2)" strokeWidth={0.7} />
            <path d="M0,-15 L-3.5,-8 L0,-10.5 L3.5,-8 Z" fill="rgba(0,212,255,0.45)" />
            <text
              y={2}
              textAnchor="middle"
              fill="rgba(0,212,255,0.5)"
              fontSize={10}
              fontWeight="700"
              fontFamily="'Plus Jakarta Sans', sans-serif"
            >
              N
            </text>
          </g>

          {/* ── Layer 10: Scale bar ───────────────── */}
          <g transform={`translate(30, ${VB_H - 28})`}>
            <line x1={0} y1={0} x2={90} y2={0} stroke="rgba(160,174,192,0.3)" strokeWidth={0.8} />
            <line x1={0} y1={-3} x2={0} y2={3} stroke="rgba(160,174,192,0.3)" strokeWidth={0.8} />
            <line x1={45} y1={-2} x2={45} y2={2} stroke="rgba(160,174,192,0.3)" strokeWidth={0.8} />
            <line x1={90} y1={-3} x2={90} y2={3} stroke="rgba(160,174,192,0.3}" strokeWidth={0.8} />
            {['0', '75', '150m'].map((t, i) => (
              <text
                key={t}
                x={i * 45}
                y={12}
                textAnchor="middle"
                fill="rgba(160,174,192,0.35)"
                fontSize={7}
                fontFamily="'JetBrains Mono', monospace"
              >
                {t}
              </text>
            ))}
          </g>
        </svg>
      </div>

      {/* ── Footer: Legend + Summary ───────────────── */}
      <div className="surveillance-map-footer">
        <div className="surveillance-map-legend">
          <span className="stm-legend-chip">
            <span className="stm-legend-swatch tunnel" />
            Tunnel Network
          </span>
          <span className="stm-legend-chip">
            <span className="stm-legend-swatch worker" />
            Worker Position
          </span>
          <span className="stm-legend-chip">
            <span className="stm-legend-swatch rescue" />
            Rescue Path
          </span>
          <span className="stm-legend-chip">
            <span className="stm-legend-swatch hazard" />
            Hazard Zone
          </span>
        </div>

        <div className="surveillance-map-summary">
          <div className="stm-summary-item">
            <span className="stm-summary-label">Zone</span>
            <span className="stm-summary-value zone">{zone || '—'}</span>
          </div>
          <div className="stm-summary-item">
            <span className="stm-summary-label">RSSI</span>
            <span className="stm-summary-value rssi">
              {rssi != null ? `${rssi} dBm` : '—'}
            </span>
          </div>
          <span className="stm-summary-note">Estimated by signal strength</span>
        </div>
      </div>
    </div>
  );
}
